export type GroupChannels = { readonly [K in ChannelGroup]: readonly ChannelName[] }
export const CHANNELS_BY_GROUP: GroupChannels = {
  chassis: ['speed', 'vx', 'vy', 'yaw_rate', 'accel_lateral', 'accel_longitudinal', 'roll', 'pitch'],
  imu: ['imu_accel_x', 'imu_accel_y', 'imu_accel_z', 'imu_gyro_x', 'imu_gyro_y', 'imu_gyro_z'],
  powertrain: ['ice_rpm', 'mgu_k_rpm', 'gear', 'throttle_pct', 'clutch_pct', 'ice_torque_nm', 'mgu_k_power_kw', 'boost_remaining_bar', 'eso_pct', 'fuel_flow_kg_h'],
  aero: ['aero_mode', 'fw_flap_deg', 'rw_flap_deg', 'zone_id', 'downforce_n', 'cl_a', 'cd_a'],
  wheel: ['wheel_speed_fl', 'wheel_speed_fr', 'wheel_speed_rl', 'wheel_speed_rr', 'slip_ratio_fl', 'slip_ratio_fr', 'slip_ratio_rl', 'slip_ratio_rr', 'slip_angle_fl', 'slip_angle_fr', 'slip_angle_rl', 'slip_angle_rr', 'vertical_load_fl', 'vertical_load_fr', 'vertical_load_rl', 'vertical_load_rr', 'camber_fl', 'camber_fr', 'camber_rl', 'camber_rr'],
  wheel_thermal: ['suspension_travel_fl', 'suspension_travel_fr', 'suspension_travel_rl', 'suspension_travel_rr', 'tyre_pressure_fl', 'tyre_pressure_fr', 'tyre_pressure_rl', 'tyre_pressure_rr', 'tyre_temp_fl', 'tyre_temp_fr', 'tyre_temp_rl', 'tyre_temp_rr', 'brake_temp_fl', 'brake_temp_fr', 'brake_temp_rl', 'brake_temp_rr'],
  thermal: ['engine_temp', 'gearbox_temp', 'coolant_temp', 'brake_duct_air_temp'],
  session: ['lap_index', 'sector_index', 'lap_time', 'sector_time', 'delta'],
  driver: ['brake_pressure', 'steering_angle', 'pedal_travel'],
}

