export function channelsForGroup(group: ChannelGroup): readonly ChannelSpec[] {
  return CHANNELS_BY_GROUP[group].map((name) => CHANNELS[name])
}

export function cornerChannels(baseName: string): readonly ChannelSpec[] {
  return CHANNEL_NAMES.map((name) => CHANNELS[name]).filter(
    (channel) => channel.baseName === baseName,
  )
}

export function channelRateHz(name: ChannelName): number | null {
  return CHANNELS[name].rateHz
}
